import six
from datetime import datetime


class ExtendedQueryResult(object):

    def __init__(self, result, query_data_timestamp, query_end_timestamp, query_expression):
        """"ExtendedQueryResult
        :param object result: Result of query
        :param float query_data_timestamp: query_data_timestamp
        :param float query_end_timestamp: query_end_timestamp
        :param query_expression: query_expression
        """
        self.result = result
        self.query_data_timestamp = query_data_timestamp
        self.query_end_timestamp = query_end_timestamp
        self.query_expression = query_expression

    def __str__(self):
        return str(self.result)


class InfoModelObject(dict):
    """InfoModel data object."""

    def __init__(self, dist_name, data):
        """
        :param string dist_name: Location of InfoModel object.
        :param dictionary data: InfoModel object data
        """
        self.dist_name = dist_name
        for name, value in six.iteritems(data):
            self[name] = self._wrap(name, value)

    def _wrap(self, name, value):
        return InfoModelObject(name, value) if isinstance(value, dict) else value

    def __getattr__(self, attr):
        return self[attr]

    def __setattr__(self, attr, value):
        self[attr] = value

    def __str__(self):
        return "InfoModelObject {}: {}".format(self.dist_name, super(InfoModelObject, self).__str__())


class InfoModelChangeSet(object):
    """InfoModel change set object"""

    def __init__(self, changeset_dict):
        date = datetime.fromtimestamp(changeset_dict["timestamp"] / 1000.0)
        self.timestamp = date.strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
        self.action = changeset_dict["action"]
        self.object = InfoModelObject(changeset_dict["dist_name"], changeset_dict["data"])

    def __str__(self):
        return "{} {} {}".format(self.timestamp, self.action, self.object.dist_name)


class InfoModelChangeSetsContainer(dict):
    """InfoModel change set objects container"""

    def __init__(self, data):
        """
        :param dictionary data: indexed Infomodel raw change sets
        """
        self.data = data
        for key, value in six.iteritems(self.data):
            self[key] = [InfoModelChangeSet(raw_changeset) for raw_changeset in value]

    def __getattr__(self, attr):
        return self[attr]

    def __setattr__(self, attr, value):
        self[attr] = value

    def __len__(self):
        return len(self.data)
